// --- 第1步：从触发器中捕获信息 ---
const clientName = '{{match.1}}';
const specialRequestText = '{{match.2}}'.trim();
const specialRequestTimes = '{{match.3}}';

// --- 第2步：直接获取姑娘的详细数据 ---
const girlName = '{{get:name}}';
const basePrice = Number({{get:price}});
const talent = '{{get:talent}}';

// --- 第3步：核心价格计算 ---
let talentBonus = 0;
if (talent.includes('舞')) talentBonus += 10;
if (talent.includes('音律')) talentBonus += 15;
if (talent.includes('口技')) talentBonus += 25;

const devMap = {'璞玉': 0, '初绽': 5, '承露': 15, '烂熟': 30, '极乐': 60};
let devBonus = (devMap['{{get:dev_mouth}}'] || 0) + (devMap['{{get:dev_breasts}}'] || 0) + (devMap['{{get:dev_vagina}}'] || 0) + (devMap['{{get:dev_anus}}'] || 0);

let specialBonus = 10 * Number(specialRequestTimes) || 0;

const totalRevenue = basePrice + talentBonus + devBonus + specialBonus;
const yourCut = Math.round(totalRevenue * 0.2);
const brothelCut = totalRevenue - yourCut;

// --- 第4步：【重构】随机满意度与最终销债计算 ---
let tip = 0;
let tipMessage = ''; // 用于在账单中显示打赏信息的HTML片段

if (Math.random() > 0.85) { // 15%的几率触发打赏
    tip = Math.floor(Math.random() * 20) + 10;
    // 预先发送喜报
    /send `<div style="background-color: #4A2545; border: 1px solid #FFD700; padding: 10px; border-radius: 5px; color: white; font-family: 'KaiTi', 'STKaiti', serif;"><strong><font color="#FFD700">【意外之喜】</font></strong><br>‘${clientName}’对‘${girlName}’的服务极为满意，额外打赏<font color="#FF69B4">${tip}</font>两！(赏钱已入您账下)</div>`
    // 准备要在账单中插入的HTML行
    tipMessage = `<li><b>恩客打赏：</b> +${tip} 两</li>`;
}

const totalDeduction = yourCut + tip; // 您本次销债的总额 = 分红 + 打赏
const finalNewDebt = Number({{get:debt}}) - totalDeduction;

// 【关键】执行唯一一次、最准确的债务更新
/set debt " + finalNewDebt + "

