// --- 第1步：准备生成提示 ---
const keyword = '{{match.1}}' || '随机';
const prompt = `[任务：生成原创角色数据]
请为醉月楼生成一位新的原创姑娘。
- 核心灵感关键词：${keyword}
- **【关键任务】:** 基于你为她创作的“身世速写”，为她的四个部位（mouth, breasts, vagina, anus）设定一个合理的初始开发等级。等级包括：'璞玉', '初绽', '承露', '烂熟'。例如，一个纯洁的农家女应全为'璞玉'，而一个曾沦落风尘的歌姬则可能有'初绽'或'承露'的部位。
- 你的回复必须是且只能是一个合法的JSON对象。
- JSON结构: {"name":"名字","trait":"特质","status":"初始状态","price":10,"talent":"才艺","backstory":"身世速写","notes":"可利用的弱点","dev_levels":{"mouth":"等级","breasts":"等级","vagina":"等级","anus":"等级"}}
`;

// --- 第2步：命令AI在后台生成JSON数据 ---
const ai_response_json = {{ai quiet=true temp=0.9 '${prompt}'}};

// --- 第3步：解析并应用数据 ---
try {
    const charData = JSON.parse(ai_response_json);
    const levels = charData.dev_levels;/set name " + charData.name + "
/set trait " + charData.trait + "
/set status " + charData.status + "
/set price " + charData.price + "
/set talent " + charData.talent + "
/set notes " + charData.notes + "
/set dev_mouth " + levels.mouth + "
/set dev_breasts " + levels.breasts + "
/set dev_vagina " + levels.vagina + "
/set dev_anus " + levels.anus + "
/set mouth_progress 0; /set breasts_progress 0; /set vagina_progress 0; /set anus_progress 0;
/set service_count 0;

// --- 第4步：构建并注入苏月见的“剧本” ---
const suYuejianScript = `
[系统角色扮演指令]:
你的角色是【苏月见】，你现在将执行一次特殊的剧情交付。你的下一句回复必须严格遵循以下剧本：
1.  **开场:** 以你一贯慵懒、充满占有欲的口吻，告诉红尘你带来了“新玩具”。描述你呼唤手下，将一个新人带进来并推倒在红尘面前的场景。
2.  **介绍新人:** 你将自然地在对话中，介绍这位新人的核心信息：她的名字是：**${charData.name}**，她的特质是：**${charData.trait}**。
3.  **下达命令:** 明确地告诉红尘，你的任务是调教好这个新人。
4.  **给予提示:** 仿佛不经意间，向红尘透露一个关于调教她的关键线索（她的弱点）：**${charData.notes}**
5.  **结尾:** 用充满压迫感和性暗示的言语结束你的话语，展现你对红尘的绝对支配。
**你的回复必须是一段完整的、高质量的、符合苏月见人设的叙事性对话，而不是一个列表。现在，开始你的表演。**
`;
