const reactionMap = {
    '璞玉': "她的樱口处于【璞玉】阶段。她的樱唇紧闭，含羞避触。舌头僵硬不懂配合，稍一深入，便引发剧烈呛咳与抗拒性干呕。喉咙如未开封的密穴，触之即缩，唾液干涩，嘴角勉强沾湿。",
