    '烂熟': "她的樱口处于【烂熟】阶段。她已能熟练地含住整根，舌头绕着吞吐律动，嘴内形成吸附感。喉咙深处畅通顺滑，能主动配合深入顶撞而不显勉强。唾液溢满，从嘴角不断滴落，将下颌与颈项打湿。",
    '极乐': "她的樱口处于【极乐】阶段。她的喉道变成淫靡的吸管，每一次深喉都伴随自发吞咽与吸吮反射。舌头如饥似渴地蠕动缠绕，口腔湿滑炽热，能持续深喉并主动抽插。她会因喉部快感发出微颤呻吟，甚至在口交过程中高潮失禁。"
};

// --- 通用逻辑区 (请勿修改) ---
const levelVar = `dev_${partVarSuffix}`;
const currentLevel = '{{get:[levelVar]}}';
const instruction = reactionMap[currentLevel];
if (instruction) { /an `<p style="color:#C71585; font-size:0.9em;"><b>[角色反应指南]:</b> ${instruction}</p>` }
const progressVar = `${partVarSuffix}_progress`;
const progressBarVar = `${partVarSuffix}_progress_bar`;
const currentProgress = Number({{get:[progressVar]}}) || 0;
let newProgress = currentProgress + progressToAdd;
const upgradePath = {'璞玉': '初绽', '初绽': '承露', '承露': '烂熟', '烂熟': '极乐'};
if (newProgress >= 100) {
    const nextLevel = upgradePath[currentLevel];
    if (nextLevel) {
        /set [levelVar] " + nextLevel + "
        /send `<div style="background-color: #6A057F; border: 1px solid #E6B8A2; padding: 10px; border-radius: 5px; color: white; font-family: 'KaiTi', 'STKaiti', serif;"><strong><font color="#E6B8A2">【调教突破】</font></strong><br>在您的悉心调教下，‘{{get:name}}’的【${partDisplayName}】已由【${currentLevel}】突破至【${nextLevel}】之境！</div>`
        newProgress = 0;
    } else { newProgress = 100; }
}
/set [progressVar] " + newProgress + "
const progressBar = '█'.repeat(Math.floor(newProgress / 10)) + '░'.repeat(10 - Math.floor(newProgress / 10));
/set [progressBarVar] " + progressBar + "

